from dataclasses import asdict, fields

def project(obj, requested: set[str]) -> dict:
    allowed = {f.name for f in fields(obj)}
    if unknown := requested - allowed:
        raise ValueError(f"unknown fields: {sorted(unknown)}")
    return {k: v for k, v in asdict(obj).items() if k in requested}
